// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":4,"question":"ما حكم الاحتفاظ ببعض الحيوانات الحقيقية، ولكنها محنّطة، وذلك في المنازل وغيرها؟","title":"حكم الاحتفاظ بالحيوانات المحنّطَّة","answer":"الجواب: الاحتفاظ بالمُحنّطة فيه نظر، وقد صدر منا في هيئة الإفتاء فتوى بالمنع من ذلك لأمرين: أحدهما: ما فيه من إضاعة المال. والثاني: أنه مصيبة إلى شرٍّ كبيرٍ: إمَّا إلى اعتقاد فيه وأنه يحفظ البيت من الجنِّ، أو من كذا، أو من كذا، أو إلى إيجاد المُصورات واتِّخاذ الصور في البيوت وتعليقها، فهي وسيلةٌ لهذا أو هذا أو لهما جميعًا؛ لاعتقاد أنَّ هذا الحيوان المُحنّط إذا جُعل في البيت أو في غرفةٍ أو في الحائط أو كذا فقد يكون سببًا لصيانة البيت من كذا وكذا وكذا، أو يكون وسيلةً إلى اتِّخاذ الصور، فإنَّ مَن يراه قد يظنُّه صورةً ويقول: فلانٌ علَّق الصورة في بيته، فيكون وسيلةً للاقتداء به والتَّأسي به، فالذي أراه والذي أفتيتُ به هو المنع والتَّحريم.","link":"https://binbaz.org.sa/fatwas/2749/حكم-الاحتفاظ-بالحيوانات-المحنطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0254.mp3","categories":["أحكام الحيوان"]},{"id":69,"question":"سائلة تقول: يتأذّى بعض الناس من القرود حيث تدخل إلى منازلنا، وتشرب من ماء المسبح، فهي تنقل الأمراض المعدية، هل يجوز قتلها بوضع سم لها؟","title":"حكم قتل القرود التي تدخل البيوت بالسُّم؟","answer":"الجواب: إذا كانت تؤذي؛ لا بأس، وإلا تُطرد بغير القتل، تطرد بالعصا، أو بغيرها بالحجارة ويكفي، فإذا كانت تؤذي؛ جاز قتلها.","link":"https://binbaz.org.sa/fatwas/2987/حكم-قتل-القرود-التي-تدخل-البيوت-بالسم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0046.mp3","categories":["أحكام الحيوان"]},{"id":192,"question":"أنا صاحب إبلٍ، أُصيبت إحداها بمرضٍ مُعْدٍ، فخشيتُ على الإبل الأخرى، فلم أستطع إبعادها؛ فقمتُ بإحراقها، فما الحكم في ذلك؟","title":"حكم إحراق الإبل المصابة بأمراض معدية؟","answer":"الجواب: إذا ذبحها وبعد ذلك أحرقها؛ لا بأس، فيذبحها قبل، وإذا ذبحها ولم يتيسر أنَّ أحدًا يُريدها يحرقها، أمَّا إن وجد مَن يأكلها من الفقراء فتُعطيها الفقراء؛ لأنَّ بعض الناس يأكلها ولا يضرّه الجرب، فالنار تُزيل ذلك، فإذا طُبِخَتْ قد لا يضرّه، فقد بلغنا فيما مضى أن أناسًا يأكلونها في وقت الحاجة ولا تضرّهم، وإن ضرَّتهم بشيءٍ يسيرٍ يزول.\nفلو لم يكن عنده أحدٌ يحتاج إليها ولا يأكلها؛ أحرقها بعد الذبح حتى لا يحصل بسببها ضررٌ على الإبل الأخرى، فالنبي ﷺ قال: لا يُورد ممرضٌ على مُصحٍّ يعني: لا تُخالط الإبل المريضة بالصَّحيحة من باب تجنب أسباب الشر، وإن كان لا عدوى؛ فالنبي قال: لا عدوى، ولا طيرة، لا عدوى: ليس شيءٌ يُعدي بطبعه، ولكن الله جعل الاختلاط -اختلاط الصحيح بالمريض- من أسباب إصابة الصحيح، فإذا أبعدها في جهةٍ أخرى، في محلٍّ آخر، أو أعطاها أحدًا من الناس إذا وجد أحدًا يقبلها؛ فهذا أولى من إحراقها، فإن لم يتيسَّر ذبحَها ثم أحرقها.\nس: يُفهم من السؤال أنه أحرقها من دون ذبحٍ؟\nالشيخ: إحراقها وهي حية ما يجوز، لا بدّ من ذبحها ثم الإحراق بعد ذلك.","link":"https://binbaz.org.sa/fatwas/3767/حكم-احراق-الابل-المصابة-بامراض-معدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0198.mp3","categories":["أحكام الحيوان"]},{"id":489,"question":"بعض الأجهزة الكهربائية تصطاد الحشرات بالكهرباء، ما حكمها؟","title":"حكم اصطياد الحشرات بالأجهزة الكهربائية","answer":"الجواب: لا، ما ينبغي، النار لا يُعَذِّب بها إلا الله، ولكن تُعالج الحشرات بغير كهرباء، الكهرباء نار.\n(دروس شرح بلوغ المرام، كتاب الأطعمة)","link":"https://binbaz.org.sa/fatwas/6248/حكم-اصطياد-الحشرات-بالاجهزة-الكهرباىية","audio":"https://files.zadapps.info/binbaz.org.sa/kahrb050 .mp3","categories":["أحكام الحيوان"]},{"id":731,"question":"هل الحيوانات المُحنَّطة جائزٌ وضعها في البيت أم حرامٌ؟","title":"هل يجوز وضع حيوانات محنَّطة في المنزل؟","answer":"الجواب: قد صدر منا جوابٌ في هذا -أنا واللجنة الدائمة- بمنع ذلك، منع الحيوانات هذه التي هي محنَّطة؛ لأنها تُشبه الصور، وقد يجرّ ذلك الناس إلى وضع الصور، ويظنون أنها صور، فينفتح باب الصور. ومن ذلك أنها من باب العبث، من باب إضاعة المال. ومن ذلك وجهٌ ثالثٌ وهو أنَّ بعض الناس قد يعتقد فيها أنَّ وجودها في البيت -ذئب محنط، أو نسر محنط، أو نمر محنط، أو كذا، أو كذا- أنه قد يمنع الجنَّ، وقد ينفع في كذا، وقد يُسبب كذا؛ فينفتح باب شرٍّ كبيرٍ وعقائد باطلة.\nفالواجب هو منع المحنَّطة هذه، وعدم إيجادها في البيت، وعدم استعمالها في البيت، كعدم استعمال تعليق الصور.","link":"https://binbaz.org.sa/fatwas/20621/هل-يجوز-وضع-حيوانات-محنطة-في-المنزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0552هل الحيوانات المحنطة جائز وضعها في المنزل أم حرام؟فتاوى المحاضرات.mp3","categories":["أحكام الحيوان"]},{"id":1778,"question":"بعض الناس يكون لديه بهيمة مريضة مشرفة على الموت، فيقوم برميها لإراحتها من المرض؟","title":"ما المشروع في التعامل مع البهيمة المريضة؟","answer":"الجواب:\nما هو بلزوم، إن ذبحها فلا بأس، وإن تركها فلا بأس، إن أراد أحدٌ الانتفاع بها يبيعها له، وإن كان ما يبغي الانتفاع بها..... إن تركها حتى تموت فلا بأس، وإن ذبحها لعلَّ أحدًا يأكلها فلا بأس.\nس: يذبحها لغير الانتفاع؟\nج: إن ذبحها فلا بأس، لعل أحدًا يأكلها إن كانت مباحةً: كالشاة، ونحوها.\nس: هي مريضة؟\nج: بعض الناس قد يأكلها ولو مريضة.","link":"https://binbaz.org.sa/fatwas/21885/ما-المشروع-في-التعامل-مع-البهيمة-المريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع البهيمة المريضة.mp3","categories":["أحكام الحيوان"]},{"id":1781,"question":"حديث ابن عمر رضي الله عنهما: أنَّ النبي ﷺ أمر بقتل الكلاب؟","title":"ما حكم قتل الكلاب؟","answer":"الجواب:\nثم نهى عن ذلك، أمر بقتلها ثم نهى، نُسخ، وقال: إنها أُمَّة من الأمم، ونهى عن قتل الكلاب إلا الأسود والعقور.","link":"https://binbaz.org.sa/fatwas/21888/ما-حكم-قتل-الكلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأمر بقتل الكلاب.mp3","categories":["أحكام الحيوان"]},{"id":1787,"question":"هناك آلة كهربائية تقتل النَّاموس؟","title":"ما حكم قتل الناموس بالكهرباء والنار؟","answer":"الجواب:\nهذا نار، يُسمَّى نارًا.\nس: ما فيه مانع؟\nج: لا يُقتل به، الكهرباء من النار.\nس: غير جائز؟\nج: يقتل بآلةٍ أخرى غير النار.","link":"https://binbaz.org.sa/fatwas/21894/ما-حكم-قتل-الناموس-بالكهرباء-والنار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قتل الناموس بالنار.mp3","categories":["أحكام الحيوان"]},{"id":1788,"question":"في فترة الصيف يكثر النملُ في دورات المياه، فمثلًا لو رشَّ عليها ماءً ليتخلص منها هل فيها شيء؟","title":"حكم رش الماء على النمل في البيوت","answer":"الجواب:\nتقصد: الماء الحار؟\nس: لا، ماء عادي.\nج: الماء العادي ما فيه شيء.","link":"https://binbaz.org.sa/fatwas/21895/حكم-رش-الماء-على-النمل-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التخلص من النمل في البيوت.mp3","categories":["أحكام الحيوان"]},{"id":1925,"question":"بالنسبة لكلب الحراسة في المنازل الكبيرة مثل القصور؟","title":"حكم الكلب لحراسة المنزل وكشف المجرمين","answer":"الجواب:\nلا، ما يصلح، إلا في هذه الثلاثة فقط: الحرث، والماشية، والصيد.\nس: ما يدخل فيها هذا؟\nج: لا، ما يدخل فيها.\nس: الكلب الذي يُستعمل في كشف المجرمين؟\nج: هذا محل نظر، الكلاب البوليسية -على ما قالوا- محل نظر، وظاهر الأحاديث منعها، وأن يُكتفى بالرجال.","link":"https://binbaz.org.sa/fatwas/22038/حكم-الكلب-لحراسة-المنزل-وكشف-المجرمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم كلب الحراسة في المنازل والمستعمل في كشف المجرمين.mp3","categories":["أحكام الحيوان"]},{"id":1926,"question":"بعضهم يضع جرسًا حول عنق بعض الأغنام؟","title":"حكم وضع جرس حول عنق الأغنام","answer":"الجواب:\nيُمْنَع.\n\nس: يضعونه في بعض الخِراف وتمشي أمام الغنم؟\n\nج: لا، ما يصلح هذا.\n\nس: الآن هذا موجود في الرعايا كلها؟\n\nج: الجاهل يُعلَّم، فالدِّين النَّصيحة.","link":"https://binbaz.org.sa/fatwas/22039/حكم-وضع-جرس-حول-عنق-الاغنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وضع جرس حول عنق بعض الأغنام.mp3","categories":["أحكام الحيوان"]},{"id":2063,"question":"امرأة تُعاني من كثرة النَّمل في البيت؟","title":"ما حكم قتل النمل في البيوت؟","answer":"الجواب:\nإذا آذى؛ لا بأس بإتلافه، لكن بغير النار، أمَّا إذا لم يُؤْذِ فلا يُتَعَرَّض له، فالرسول نهى عن قتل النملة والنحلة والهدهد والصُّرَد، لكن إذا آذى يُقْتَل.","link":"https://binbaz.org.sa/fatwas/22181/ما-حكم-قتل-النمل-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قتل النمل في المنزل.mp3","categories":["أحكام الحيوان"]},{"id":2565,"question":"يجوز اقتناء الحيوانات المُحَنَّطة؟","title":"هل يجوز اقتناء الحيوانات المُحَنَّطة؟","answer":"الجواب: ما ينبغي هذا؛ لأن فيها مفاسد، قد يُعتقد فيها شيء من الاعتقادات الفاسدة اللي يعلّقونها في بيوتهم، وقد يتأسّى بهم غيرهم ويحط المصوَّرات، الصور، وقد يقال إنها من إضاعة المال؛ إذ لا زينة في هذا ولا خير في هذا.","link":"https://binbaz.org.sa/fatwas/22697/هل-يجوز-اقتناء-الحيوانات-المحنطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اقتناء الحيوانات المحنطة.mp3","categories":["أحكام الحيوان"]},{"id":3028,"question":"سؤالي هو أنني أضع الوَسْم على خد الناقة وإذا تركته ووضعته في مكان آخر فأخشى أن أضع وَسْم قبيلة أخرى، ووسوم القبائل معروفة، فما هو رأي سماحتكم؟","title":"حكم الوَسْم على وجه الحيوان","answer":"الجواب: ما يجوز الوَسْم في الوجه، ما يجوز الوَسْم في الوجه، ما يجوز الرسول ﷺ نهى عن ذلك، نهى عن وَسْم الوجه لكن يضع وَسْمًا في جهة أخرى تخالف وَسْم الناس، في العَضُد، في الفَخِذ، في الأذن؛ ما في بأس، أما الوجه لا.\nس: حدود الوجه؟\nالشيخ: الوجه معروف، محل الأنف ومحل الفم ومحل العينين، أما الأذن ما هي من الوجه، الأذن من الرأس، تَبَع الرأس.","link":"https://binbaz.org.sa/fatwas/23188/حكم-الوسم-على-وجه-الحيوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الوسم على الوجه.mp3","categories":["أحكام الحيوان"]},{"id":3302,"question":"حمر الوحش الشائع عند الناس أنها المخططة، ويقول بعض الباحثين أنها بعد البحث والاستقراء في كتب الحيوان ما أثبت أحدهم أنها هذه، اللهم إلا في بعض المراجع المتأخرة، وسألت بعض أهل البيئة والفطريات فقالوا: الدارج عند الناس أنها المخططة، وهذا عندنا من الأهلية، أما الوحش فهو اللي يسمى بالوُضيحي، فما قولكم؟","title":"ما صفة الحُمُر الوحشية؟","answer":"الجواب: حُمُر الوحش معروفة أنها المخططة، في حياة الحيوان ذكر الموضوع في إفراد حياتها وبيان وصفها، أما الوُضيحي غير.","link":"https://binbaz.org.sa/fatwas/23467/ما-صفة-الحمر-الوحشية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة الحُمُر الوحشية.mp3","categories":["أحكام الحيوان"]},{"id":4537,"question":"سؤر البغل والحمار؟","title":"حكم سؤر البغل والحمار","answer":"الجواب: طاهر على الصحيح مثل الهرة، بل من باب أولى، الهرة قد يكون أكلها النَّجاسة أكثر، أما الحمار والبغل يُعلفان علفًا طاهرًا، فإذا كانت الهرة وهي قد تصيد الفأر وغير الفأر ومع هذا النبيُّ ﷺ أذن في استعمال فضلتها، فالبغل والحمار من باب أولى.","link":"https://binbaz.org.sa/fatwas/24817/حكم-سور-البغل-والحمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم سؤر البغل والحمار.mp3","categories":["أحكام الحيوان"]},{"id":4683,"question":"الوزغ يُقتل؟","title":"حكم قتل الوزغ في الحرم","answer":"الجواب: في الحلِّ والحرم مثله، الوزغ من أقبحها، يُقتل في الحلِّ والحرم.","link":"https://binbaz.org.sa/fatwas/24975/حكم-قتل-الوزغ-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قتل الوزغ في الحرم.mp3","categories":["أحكام الحيوان"]},{"id":4684,"question":"ولو عدا عليه ضبع؟","title":"هل يُقتل الضبع المؤذي في الحرم؟","answer":"الجواب: والضبع كذلك؛ لأنه وإن كان صيدًا لكن إذا آذى يُقتل، من جنس المؤذيات الأخرى.","link":"https://binbaz.org.sa/fatwas/24976/هل-يقتل-الضبع-الموذي-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا عدَّى عليه ضبع في الحرم، فهل يقتله.mp3","categories":["أحكام الحيوان"]},{"id":4685,"question":"كونه عليه الصلاة والسلام أمر بقتل الأسودين: الحية والعقرب في الصلاة، ولو كانت من حيات البيوت غير ذي الطفيتين والأبتر: هو بغير إنذار، أو مخصوص بمَن أُنذرت؟","title":"هل تُقتل الحيةُ والعقربُ في الصلاة بغير إنذار؟","answer":"الجواب: يحتمل أنَّ هذا ناسخ لحديث أبي سعيد، إطلاق النبي ﷺ في هذه الخمس وما جاء في معناها، يُحتمل أنه ناسخ لما جاء في مسألة جن البيوت، وأنها تُقتل مطلقًا، وأن ذلك منسوخ.  ويحتمل أنه مُحكم، وأن مُراده ﷺ الحيَّات التي هي غير جنان البيوت، كالتي توجد في المساجد، في الطرقات، في البرية، تُقتل، أما الحية في المسكن فتُنذر ثلاثًا، فإن عادت تُقتل كما جاء في الحديث: إنَّ لهذه البيوت جنانًا من الجنِّ، وقد تبرز بصورة الحية، فلا تُقتل حتى تُنذر ثلاث مرات.\nس: ثلاث مرات ولو في يومٍ واحدٍ؟\nج: ولو في يومٍ واحدٍ، إذا أُنذرت ثلاثًا، في بعضها: ثلاث مرات، وفي بعضها: ثلاثة أيام، وفي بعضها: ثلاثًا، والحاصل أنَّ الإنذار ثلاث مرات، سواء في يومٍ واحدٍ أو في أيام.\nس: الأقرب التَّخصيص وأنَّ هذه مخصوصة من عموم الحديث؟ أن جنان البيوت مُستثناة؟\nج: الأقرب على القاعدة: الخاص يقضي على العام، هذه قاعدة.","link":"https://binbaz.org.sa/fatwas/24977/هل-تقتل-الحية-والعقرب-في-الصلاة-بغير-انذار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في قتل الحيات والعقرب، ونحوها في المسكن.mp3","categories":["أحكام الحيوان"]},{"id":4857,"question":"حكم اقتناء الكلب لحراسة المنزل؟","title":"ما حكم اقتناء الكلب لحراسة المنزل؟","answer":"لا، ما أباحه النبي ﷺ إلا لثلاثة: الصيد والماشية والزرع .","link":"https://binbaz.org.sa/fatwas/25323/ما-حكم-اقتناء-الكلب-لحراسة-المنزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اقتناء الكلب لحراسة المنزل.mp3","categories":["أحكام الحيوان"]},{"id":4858,"question":"بعض الدول تذبح الدجاج بالصعق الكهربائي أو بالخنق فكيف يفعل الشخص إذا لم يجد إلا هذه الوسيلة، يأكل منها؟","title":"حكم الأكل مما ذُبح بالصعق أو الخنق؟","answer":"لا، هذه ميتة.\nس: وهل لا بدّ من ثبوت هذا لديه؟\nج: إن كانت من ذبائح أهل الكتاب تحل له، إلا أن يثبت له أن ذبحت بغير الشرع كالصعق أو بغيره، أما إذا كان من ذبيحة المجوس أو الوثنيين فهذه تحرم مطلقًا.","link":"https://binbaz.org.sa/fatwas/25324/حكم-الاكل-مما-ذبح-بالصعق-او-الخنق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأكل مما ذُبح بالصعق الكهربائي أو الخنق.mp3","categories":["أحكام الحيوان","الذكاة والصيد"]},{"id":4865,"question":"الحيوانات البرمائية التي تعيش في الماء والبر: كالتمساح، والسرطان، ونحو ذلك، هل يجوز أكلها؟","title":"ما حكم الحيوانات البرمائية كالتمساح، والسرطان؟","answer":"إذا كان يعتدي يصير سبعًا، والله حرَّم السباع، أما إذا كان يعيش في البحر فالصواب أنَّ صيد البحر كله حلال.","link":"https://binbaz.org.sa/fatwas/25338/ما-حكم-الحيوانات-البرماىية-كالتمساح-والسرطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحيوانات البرمائية.mp3","categories":["أحكام الحيوان"]},{"id":4866,"question":"مَن كانت تأكل روثها من الحيوانات وغيرها، تكون من الجلَّالة أم لا؟","title":"هل تعتبر الحيوانات التي تأكل روثها من الجلَّالة؟","answer":"لا، روثها طاهر، ما تكون جلَّالةً، إذا أكلت البقرةُ من روثها، والشاة من روثها، ما تصير جلالةً، الجلالة تأكل النَّجاسة.","link":"https://binbaz.org.sa/fatwas/25339/هل-تعتبر-الحيوانات-التي-تاكل-روثها-من-الجلالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحيوانات التي تأكل روثها هل تعتبر من الجلالة.mp3","categories":["أحكام الحيوان"]},{"id":4867,"question":"جميع حيوانات البحر مُطلقًا حلال؟","title":"هل جميع حيوانات البحر حلال مُطلقًا؟","answer":"هذا هو الصواب، وبعض أهل العلم يستثني منها ما كان مُحرَّمًا في البرِّ: كالناب، ولكن ما عليه دليل، لا، ظاهر القرآن: أُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وطَعَامُهُ مَتَاعًا لَكُمْ [المائدة:96]، ظاهرها الحلّ، وكذلك قوله ﷺ في البحر: هو الطَّهور ماؤه، الحلُّ ميتته، ظاهره العموم، لكن إذا ترك الإنسانُ ما يُشبه ما في البرِّ من الحيوانات المحرَّمة: كالكلب، وأشباهه من المحرَّمات: كالذئب، والخنزير، إذا ترك هذا احتياطًا خروجًا من الخلاف فحسنٌ.","link":"https://binbaz.org.sa/fatwas/25340/هل-جميع-حيوانات-البحر-حلال-مطلقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل جميع حيوانات البحر حلال مُطلقًا.mp3","categories":["أحكام الحيوان"]},{"id":5201,"question":"سماحة الشيخ: ما حكم وسم الأنعام بالكيّ إذا لم يُوجد البديلُ عن ذلك، وخاصَّةً الإبل؟","title":"ما حكم وسم الأنعام بالكيّ في الوجه وغيره؟","answer":"الجواب: كيّها لا بأس به، فالنبي كوى، فوسمها بالكي بأن تُكوى في أفخاذها ورقابها، لا في الوجه، فالكي لا بأس به في الإبل ونحوها، في الفخذ، أو في الرقبة، أما الوجه لا، لا توسم في وجوهها، لا الإبل، ولا البقر، ولا الغنم، إنما تُكوى في الفخذ، أو في الأذن، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/30145/ما-حكم-وسم-الانعام-بالكي-في-الوجه-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 177.mp3","categories":["أحكام الحيوان"]},{"id":7943,"question":"هذه الرسالة وردت من خيبر يقول فيها من مدينة خيبر التاريخية الشمالية تابعة منطقة المدينة المنورة ومقدمها المواطن طريف حمد الشنيشني يقول فيها: أعرض على فضيلتكم هذه المشكلة التي حدثت لدينا بمدينة خيبر، يوجد في مدينة خيبر كثير من العيون وهذه العيون جميعها لا تخلو من الديدان ومخلوقات الله ومنها: السمك الكبير منه والصغير والضفادع وغيرها، وقد قامت فرقة من مكتب البلهارسيا بخيبر برش هذه العيون بمواد سامة أبادت جميع المخلوقات التي تعيش في العيون الجارية والتي نسقي منها النخيل والبساتين عموماً، وسؤالنا هو: هل في قتل المخلوقات التي في العيون الجارية وليست الراكدة حرمة أم حلال لكونه إفناء لمخلوقات الله في غير وجهه الطبيعي؟","title":"حكم رش عيون الماء بمواد سامة للمصلحة العامة","answer":"الجواب: إذا كانت الحيوانات هذه التي في العيون قد علم منها مضرة على الناس وعلى أصحاب العيون هذا له وجه رشها لأجل إزالة ضررها، أما إذا لم يكن بها ضرر وإنما ترش عبثاً هذا لا يجوز رشها، قتل ما فيها من الضفادع ولا غيرها من الحيتان بل تترك، أما إذا كانت هناك أشياء توجب رشها؛ لأن فيها أشياء سامة مؤذية تضر الناس وهذه الحيوانات التي فيها قد علم أنها مضرة بالناس الذي يشربون من هذه العيون ويسقون منها إذا علم عند الأطباء أنها ضارة وأن فيها أشياء تضر أصحاب العيون فلا بأس بقتلها إراحة للمسلمين من شرها، فإن لم يكن كذلك فلا يجوز قتلها. نعم.\nالمقدم: هو طبعاً يا سماحة الشيخ البلهارسيا لها دور كبير في ضرر الناس، ومكافحة البلهارسيا دائماً يعتنون بصحة الناس.\nالشيخ: على كل حال إذا كان هناك داع لهذا الشيء وهم يعلمون الأطباء أن هذا يضر الناس بسبب هذه الحيوانات التي وجد في هذه العيون الخاصة هذا له وجه من أجل البلهارسيا وغيرها.\nالمقصود: إذا كان هناك ضرر بين عرفوه فلهم عذر في إتلاف هذه الحيوانات إذا كان بأسبابها، أو هناك يعني ضرر يحصل في العين لكن لا يتوصل إلى إزالته والسلامة من شره إلا بهذا الرش، والرش يفني هذه الحيوانات أو يفني بعضها، فهي غير مقصودة لكن من أجل إزالة الضرر الذي في العيون في المواد التي تسبب البلهارسيا هذه التي يقولون فإن هذا عذر لهم عذر شرعي؛ لأن ما لا يتم يعني إزالة الشر إلا به فهو عذر، فالحيوان الذي في.. الحوت أو الضفدع أو ما أشبه ذلك الذي في العين، لكن لا يتوصل إلى إزالة الأدواء التي في هذا العين والشرور التي فيها إلا برشها بشيء يقتل هذه الحيوانات التي فيها فلا يضر إن شاء الله ذلك، غير متعمد قتل الضفدع إنما جاء تبعاً. نعم.\nالمقدم: هو أيضاً يقول: نخشى على هلاك الحيوانات الموجودة في بلادنا من المواد السامة عن طريق شرب الماء أو أكل العشب، وهذه الحيوانات من الخيل والبقر والأغنام وغيرها، طبعاً مثل المواد السامة هذه لا تضر الحيوانات الكبيرة مثل الخيل والأبقار.\nالشيخ: على كل حال هم يعرفون هذه .....\nالمقدم: نعم. فالمكتب يعرف هذا.\nالشيخ: الذي يكلفون بهذه الأشياء يعرفون ...\nالمقدم: نعم نعم يعرفونها جداً.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/5476/حكم-رش-عيون-الماء-بمواد-سامة-للمصلحة-العامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_068/06807.mp3","categories":["أحكام الحيوان"]},{"id":8133,"question":"يقول أيضاً: ما حكم وضع الحيوانات في حديقة الحيوانات، وحبسها لمشاهدتها؟","title":"حكم حبس الحيوانات في الحدائق للمشاهدة","answer":"الجواب: ما نعلم في هذا شيء، لا حرج في ذلك؛ لأن فيه فوائد، يعرف الناس هذه الحيوانات ويقفون عليها، لا بأس بذلك، يعرفونها ويتفرجون عليها، إذا كان الحابس لها يقوم بحاجتها، يعطيها حاجاتها من الطعام والشراب، إذا حبسها وأعطاها حاجاتها فلا حرج إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/5934/حكم-حبس-الحيوانات-في-الحداىق-للمشاهدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08805.mp3","categories":["أحكام الحيوان"]},{"id":8255,"question":"رسالة وصلت إلى البرنامج من العراق أيضاً، تقول: إني المستمعة (م. ر) من الأعظمية بغداد، إني أستمع إلى برنامجكم يومياً ونشكركم عليه لما فيه الفائدة للجميع، لذا أرسل لكم هذه الأسئلة وأرجو من حضرتكم الإجابة عليها وعدم إهمالها.والسؤال الأول: هو أنني قبل أربعين عاماً كنت مشغولة في أمور البيت فقلت لابني أن يحبس الدجاج في التنور؛ لكي أتخلص من إزعاجه؛ لأنني كنت أشتغل ونسيت أن التنور حار؛ لأنني خبزت به قبل يوم، فمات الدجاج وأنا غير متعمدة، فهل علي إثم وهل علي كفارة؟ أفيدوني جزاكم الله خيراً.","title":"من تسبب في قتل حيوان بغير تعمد","answer":"الجواب: ليس عليك شيء مادمت لم تتعمدي قتله بغير حق بهذه الطريقة وإنما هو سهو منك وغلط ليس عليك شيء، والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6063/من-تسبب-في-قتل-حيوان-بغير-تعمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09804.mp3","categories":["أحكام الحيوان"]},{"id":8351,"question":"عندما نعمد إلى تنظيف المنازل نجد فيها بيت العنكبوت المعروف لدى الجميع، فهل تجوز إزالته وهدمه، علماً بأني قرأت في أحد الكتب أن العنكبوت هي التي بنت على الغار الذي اختبأ فيه الرسول ﷺ وصاحبه أبو بكر ، فكانت ببناء هذا البيت مع قدرة الله السبب في عدم وصول المشركين إلى الرسول ﷺ وصاحبه أبو بكر والنيل منهما، كما أنه قيل لي: إنه لا يجوز قتل هذه الحشرة أو هدم منزلها بالرغم من أنها تسبب تشوهاً بالمنزل، أفيدونا أفادكم الله؟","title":"حكم إزالة بيت العنكبوت من البيوت","answer":"الجواب: لا حرج في إزالة آثار العنكبوت ولا نعلم ما يدل على كراهة ذلك، فإزالتها لا حرج في ذلك، أما كونها بنت على الغار الذي دخل فيه النبي صلى الله عليه وسلم وصاحبه أبو بكر ، فهذا ورد في بعض الأحاديث وفي صحته نظر، ولكنه مشهور، ولو فرضنا صحته فإنه لا يمنع من إزالتها من البيوت؛ لأن هذا شيء ساقه الله جل وعلا كرامةً لنبيه، ومعجزة لنبيه عليه الصلاة والسلام، وحمايةً له من كيد الكفرة، فلا يمنع ذلك إزالتها من البيوت التي ليس لوجودها حاجة فيها، ولا حرج في ذلك إن شاء الله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6169/حكم-ازالة-بيت-العنكبوت-من-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11308.mp3","categories":["أحكام الحيوان"]},{"id":8446,"question":"الحشرات التي توجد في البيت مثل: النمل والصراصير وما أشبه ذلك، هل يجوز قتلها بالماء أو بالحرق، وإن لم يجز فماذا نفعل؟","title":"حكم قتل الحشرات المؤذية بالنار","answer":"الجواب: هذه الحشرات إذا حصل منها الأذى تقتل لكن بغير النار، تقتل بالمبيدات التي غير النار؛ لأذاها فلا بأس، يقول النبي ﷺ: خمس من الدواب كلهن فواسق، يقتلن في الحل والحرم: الغراب والحدأة والفأرة والكلب العقور والعقرب، في اللفظ الآخر: والحية سادسة، فهذه أخبر النبي ﷺ عن أذاها أنها فواسق، يعني: مؤذية، قد خرجت عن طبيعة أشباه غيرها من عدم الأذى وهي مؤذية؛ فلهذا قال: يقتلن في الحل والحرم: الغراب والحدأة والفأرة والعقرب والكلب العقور، وكذلك: (الحية) كما في الرواية الأخرى عند مسلم ، فالمقصود أن هذه وما أشبهها يقتلن في الحل والحرم، فإذا وجد أذى من غيرها كالنمل إذا آذى يقتل، أو الصراصير تقتل، أو الخنافس، أو غيرها لما يؤذي يقتل، نعم، لكن بالمبيدات لا بالنار. نعم.\nالمقدم: ليس بالنار؟\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6330/حكم-قتل-الحشرات-الموذية-بالنار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12011.mp3","categories":["أحكام الحيوان"]},{"id":9335,"question":"هنا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول: أختكم في الله هلالة بنت سعود ، أختنا تقول: لقد انتشرت تربية الطيور الأليفة وحبسها وتسأل عن الحكم؟","title":"حكم تربية الطيور الأليفة وحبسها","answer":"الجواب: لا نعلم بأسًا في ذلك، سواءً كان حمامًا أو بغبغاء أو غيرها من الطيور التي ينتفع بها أو يستأنس بها أو ما أشبه ذلك مما قد ينتفع به أهل البيت إذا أحسنوا إليها بالماء والطعام ولم يظلموها فلا بأس بذلك، وإن كره هذا بعض أهل العلم لكن لا نعلم في هذا بأساً، إذا أدي الحق من جهة الشراب والطعام ولم تؤذ فالنبي ﷺ ذكر امرأة عذبت في النار في هرة حبستها لا هي أطعمتها وسقتها إذ هي حبستها ولا هي تركتها تأكل من خشاش الأرض، فهذا يدل على أن من حبس الحيوان وأطعمه وسقاه وقام بحاجته لا حرج عليه، ناقة أو بقرة أو شيئاً من الغنم أو غيره من الظباء أو غير ذلك، فهكذا الطيور التي أشار إليها السائل. نعم.","link":"https://binbaz.org.sa/fatwas/7496/حكم-تربية-الطيور-الاليفة-وحبسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_156/15602.mp3","categories":["أحكام الحيوان"]},{"id":9419,"question":"المستمع (ع. س) من بلاد غامد يسأل عن قتل البهائم السائبة التي تسبب كثيرًا من حوادث السيارات؟","title":"حكم قتل البهائم السائبة التي تسبب حوادث السيارات","answer":"الجواب: هذا فيه تفصيل: أما إذا كانت في الطرقات فالواجب إخراجها وإبعادها عن الطرقات بكل وسيلة، وإذا حصل إتلافها من غير قصد بالسيارة أو بغير السيارة فهي غير مضمونة لتفريط أهلها، وقد نبهت الدولة على ذلك، وبينت أن ما يكون في الطرقات هدر، وقد استفتت في ذلك العلماء وأفتيت في ذلك؛ لأن الضرر عظيم على أرباب السيارات وعلى المسلمين.\nفالواجب على أهل المواشي أن يصونوها وأن يكفوها عن الطرقات، وأن يجعلوها في أماكن بعيدة حتى لا تضر الناس، فكم من نفس هلكت بأسباب هذه البهائم! يحصل انقلاب، ويحصل صدام، ويحصل شر كبير.\nأما كون الإنسان يتعمد قتلها لئلا تكون في الطرقات هذا لا، لا يجوز يتعمد قتلها لا يرميها بالبندق ولا ينحرها بالسيف ولا بغيره، بل يطردها ويكفي، يطردها عن الطرقات حتى تبتعد عن الطرقات ولو جعلت الدولة من يقوم بذلك فهذا حسن، وإذا عرف إنسان يتساهل ويجعل بهائمه حول الطريق يستحق أن يعاقب أيضًا حتى يكفها عن الطريق؛ لئلا يؤذي الناس ويضر الناس بعمله السيئ، نسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/7584/حكم-قتل-البهاىم-الساىبة-التي-تسبب-حوادث-السيارات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19005.mp3","categories":["أحكام الحيوان"]},{"id":9470,"question":"وهذه رسالة من المرسل صالح أبو مروان من المكلا من حضرموت، يقول في رسالته: هل يجوز قتل دواب الأرض وحشراتها كالذر ونحوها، أم أن هناك نوعاً من الحشرات يجوز قتله وغيره لا؟","title":"حكم قتل الحشرات وغيرها","answer":"الجواب: الشيء الذي يؤذي يقتل إذا آذى الذر أو غيره من الحشرات يقتل، وهكذا العقرب والحية تقتل والفأرة والغراب، كلها أمر النبي بقتلها عليه الصلاة والسلام في الحل والحرم، الغراب والحدأة والعقرب والحية والكلب العقور، وهكذا ما يؤذي من النامس.. البعوض.. الذباب، وهكذا الذر إذا آذى يقتل وإذا ما آذى يترك نفس الذر. نعم.\nالمقدم: بارك الله فيكم، يعني القاعدة.\nالشيخ: ...... الأذى.\nالمقدم: ........ الأذى يقتل؟\nالشيخ: وهكذا ما أذن فيه النبي ﷺ يقتل.\nالمقدم: من الخمس .....؟\nالشيخ: الخمس.. وسادسها الحية، الغراب والحدأة والعقرب والفأرة والكلب العقور والحية، وهكذا السبع العادي، وهكذا الحشرات المؤذية مثل البعوض وأشباهه. نعم.\nالمقدم: الحية ألا يتمثل بها الجن فيحذر قتلها؟\nالشيخ: لا، هذا في البيوت في العامر، تحذر ثلاث مرات وتنذر فإن عادت تقتل.\nالمقدم: الحية فقط؟\nالشيخ: نعم الحية فقط عند بعض أهل العلم؛ لأن الرسول ﷺ أمر باستئذانها ثلاث مرات في العمران، أما في الطرقات وفي الصحراء لا تستأذن تقتل.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7644/حكم-قتل-الحشرات-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24107.mp3","categories":["أحكام الحيوان"]},{"id":9740,"question":"أخيراً تقول: إن هناك امرأة أمرت بنتها أن تجمع القطط الموجودة في البيت وتضعها في كيس، حتى يتخلصوا منها إذا جاء أخوها الأكبر، فيأخذها ويضعها في أحد المطاعم البعيدة؛ لأنها آذتهم، وعندما ربطتها في هذا الكيس نسيها الجميع وماتت هذه القطط، ويخشون من الوقوع في العقوبة، وعلى من يكن الإثم في هذه الحالة؟","title":"حكم قتل الحيوان نسياناً","answer":"الجواب: مادام الواقع حصل بسبب النسيان فلا شيء الحمد لله، والقطط ليس فيها الدية ولا فيها الكفارة، إذا ماتت فهي هدر ليس فيها شيء، لكن لا يجوز تعمد قتلها بغير حق، ولا جعلها بالكيس حتى تموت، لكن مادام وقع هذا نسياناً فلا شيء في ذلك، والحمد لله.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7926/حكم-قتل-الحيوان-نسيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25617.mp3","categories":["أحكام الحيوان"]},{"id":10082,"question":"يقول: هل على الإنسان إثم في قتل الحيوانات البرية الأليفة منها وغير الأليفة، إذ أني أرى بعض الناس ليس له عمل إلا صيد الحيوانات، وهو ليس جائع ويصطاد الثعالب والأرانب والضباع والذياب والوبار والغزلان والطيور بشتى أنواعها، كيف ذلك والدين الإسلامي أمر بالرفق بالحيوان؟","title":"حكم قتل الحيوانات لمجرد العبث","answer":"الجواب: إذا كان لمصلحة شرعية ليأكل أو يبيع كأن يصيد الحبارى والظباء والأرانب، وغير هذا من الأشياء المباحة ليأكلها أو ليبيعها فلا بأس، أما إذا كان يصيدها ليقتلها ويتركها هذا لا ينبغي، أقل أحواله الكراهة الشديدة، فلا يصيد حيواناً مأكولاً إلا لمصلحة إما ليأكل أو يطعمه الفقراء أو يهديه أو يبيعه أما اللعب فلا يجوز، هذا لعب لا ينبغي للمؤمن أن يفعله، وقد روي عن النبي ﷺ أنه نهى عن الصيد إلا لمأكلة. يعني: إلا ليؤكل وينتفع به، أما الحيوانات الأخرى المحرمة فإن كانت تؤذي الناس فهو مأجور في قتلها، وأما إذا كانت لا تؤذي الناس فلا يشرع له تتبعها وهي لا تؤذي أحداً، سواء كان ثعلباً أو غيره، أما إذا كان قد آذى الناس فإنه يقتل كالثعلب الذي يصيد دجاجهم أو حمامهم، أو الذئب الذي يأكل غنمهم يقتل، أما أن يتتبع سباعاً لا تؤذي أحداً ولا تضر أحداً فلا ينبغي ذلك؛ لعدم الفائدة وعدم المصلحة. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8249/حكم-قتل-الحيوانات-لمجرد-العبث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30412.mp3","categories":["أحكام الحيوان","الذكاة والصيد"]},{"id":11405,"question":"إحدى الأخوات المستمعات من القصيم الرس تقول: أختكم بنت الإسلام، أختنا تقول: أذكر أنني تسببت في قتل قطة، وحينئذ كنت صغيرة، والآن بدأت أتذكر ذلك الحادث، فماذا علي الآن؟ جزاكم الله خيرًا.","title":"حكم من تسببت في قتل قطة وهي صغيرة","answer":"الجواب: ليس عليك شيء، إذا كنت صغيرة ما بعد كلفتي؛ ليس عليك شيء، وإن كنت مكلفة قد بلغت؛ فعليك التوبة إلى الله، والندم، وعدم العودة إلى مثل هذا، نعم. المقدم: بارك الله فيكم، وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9585/حكم-من-تسببت-في-قتل-قطة-وهي-صغيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38005.mp3","categories":["أحكام الحيوان"]},{"id":11814,"question":"يقول: إن والدته تربي كلبة تحرس منزلهم ومزرعتهم، لكنها إذا جاءت بجراوة تسم هذه الجراوة وتقتلهم، ويسأل عن الحكم هل عليها كفارة؟ جزاكم الله خيرًا.","title":"حكم اقتناء الكلب لحراسة البيت","answer":"الجواب:  اقتناء الكلب للزراعة، أو الغنم، أو الصيد؛ لا بأس به، أما جعله في البيت حارسًا للبيت لا، هذا لا ينبغي، النبي ﷺ رخص في الكلب في ثلاثة، في الحرث، وفي الماشية، وفي الصيد، وما سوى ذلك يمنع، وليس لها قتل الجروة عيالها، ليس لها قتل أولاد الكلبة، بل إذا كانت لا تريدهم إذا كبروا واستغنوا عن أمهم تبعدهم، أما القتل لا، وما دامت أمهم ترضعهم لا، حتى يكبروا ويستغنوا، إذا كبروا واستغنوا عن أمهم؛ يبعدوا، وأما قبل ذلك فإبعادهم قتل، لا تقتلهم لا بالسم، ولا بغيره، نعم نسأل الله العافية. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9998/حكم-اقتناء-الكلب-لحراسة-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42316.mp3","categories":["أحكام الحيوان"]},{"id":12181,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية أيضًا، وباعثتها إحدى الأخوات من هناك تقول: سميرة مساعدة، الأخت سميرة لها عدد من الأسئلة من بينها سؤال يقول: هل يجوز تحنيط الحيوانات والطيور، وهل يجوز اقتناء هذه الحيوانات والطيور المحنطة في البيت؟","title":"حكم تحنيط الحيوانات ووضعها في البيوت","answer":"الجواب:  لا يجوز ذلك لأمرين: أحدهما: أنه عبث وإضاعة مال، والثاني: أنه يفضي إلى اعتقادات باطلة في ذلك، وربما أفضى أيضًا إلى تعليق الصور التي لذوات الأرواح، تأس بمن علق هذه الحيوانات المحنطة، فالذي نفتي به المنع من ذلك لهذين الأمرين؛ لأنه إضاعة مال؛ ولأنه قد يقضي إلى اعتقادات فاسدة، وهناك علة أخرى ثالثة قد يفضي أيضاً إلى تعليق الصور؛ لأن من رآهم ظن أنها صور فيقتدي بهم ويصور مثلهم، فالحاصل أن هذا العمل ليس بجائز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10367/حكم-تحنيط-الحيوانات-ووضعها-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_443/44308%20Editing.mp3","categories":["أحكام الحيوان"]},{"id":12391,"question":"إذا تسببت الوالدة في قتل هرة دون أن تتعمد، وقد صامت الوالدة ثلاثة أيام نتيجة لما حدث، هل تكون آثمة؟","title":"حكم قتل الهرة من غير قصد","answer":"الجواب:  لا، ليست آثمة إذا كانت لم تتعمد قتلها، لا شيء عليها لا صوم ولا غيره، وإن تعمدت فعليها التوبة، والندم، ولا حاجة إلى الصوم، تتوب إلى الله بالندم والإقلاع والعزم ألا تعود في ذلك إن كانت عامدة، أما إذا كان خطأ؛ فليس عليها شيء. المقدم: الحمد لله جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10597/حكم-قتل-الهرة-من-غير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40116.mp3","categories":["أحكام الحيوان"]},{"id":12558,"question":"نعود في هذه الحلقة إلى رسالة المستمع ناجي طه حسين إذ عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له جمع من الأسئلة من بينها سؤال يقول فيه: ما حكم تربية الكلاب؟","title":"تربية واقتناء الكلاب بين الجائز والممنوع","answer":"الجواب:  لا تجوز تربية الكلاب إلا لثلاث: للصيد، وحراسة الماشية، والحرث، كما قال النبي ﷺ: من اقتنى كلبًا -إلا كلب صيد أو ماشية أو زرع- فإنه ينقص من أجره كل يوم قيراطان ولأن في تربية الكلاب وسيلةً إلى نجاستها، وتقذيرها، وإيذاء أهل البيت بها، وقد \"أمر النبي ﷺ بغسل الإناء إذا ولغ فيه الكلب سبع مرات، أولاهن بالتراب\". فالواجب البعد عنها، والسلامة منها، إلا من احتاج إليها للصيد، أو للحرث، أو للماشية لحراسة الغنم، أما تربيتها لغير ذلك تقليدًا للنصارى، وأشباههم؛ فهذا لا يجوز، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10760/تربية-واقتناء-الكلاب-بين-الجاىز-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45702.mp3","categories":["أحكام الحيوان"]},{"id":12560,"question":"نعود في هذه الحلقة إلى رسالة المستمع ناجي طه حسين إذ عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة بقي له جمع من الأسئلة من بينها سؤال يقول فيه: ما حكم تربية الكلاب؟","title":"تربية واقتناء الكلاب بين الجائز والممنوع","answer":"الجواب:  لا تجوز تربية الكلاب إلا لثلاث: للصيد، وحراسة الماشية، والحرث، كما قال النبي ﷺ: من اقتنى كلبًا -إلا كلب صيد أو ماشية أو زرع- فإنه ينقص من أجره كل يوم قيراطان ولأن في تربية الكلاب وسيلةً إلى نجاستها، وتقذيرها، وإيذاء أهل البيت بها، وقد \"أمر النبي ﷺ بغسل الإناء إذا ولغ فيه الكلب سبع مرات، أولاهن بالتراب\". فالواجب البعد عنها، والسلامة منها، إلا من احتاج إليها للصيد، أو للحرث، أو للماشية لحراسة الغنم، أما تربيتها لغير ذلك تقليدًا للنصارى، وأشباههم؛ فهذا لا يجوز، نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10760/تربية-واقتناء-الكلاب-بين-الجاىز-والممنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_457/45702.mp3","categories":["أحكام الحيوان"]},{"id":12949,"question":"تسأل السائلة عن تربية القطط في المنازل من غير الضرورة، هل يجوز ذلك؟","title":"حكم تربية القطط في المنازل","answer":"الجواب:  لا حرج، إذا كان لا تؤذي أحدًا؛ فلا حرج في الإحسان إلى القطط في البيت، إذا كانت لا تؤذي أحدًا من الناس؛ فلا حرج في ذلك من باب الإحسان؛ لأنهم من الطوافين علينا والطوافات. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11165/حكم-تربية-القطط-في-المنازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50208.mp3","categories":["أحكام الحيوان"]},{"id":12997,"question":"هذا سائل للبرنامج يقول: أخي له مجموعة من الطيور يهتم بها، ويقضي معها معظم الأوقات، ويقوم بتربية الحمام، فهل في ذلك حرج؟","title":"صرف الوقت في تربية الحمام","answer":"الجواب:  لا حرج في ذلك إذا لم تشغله عن طاعة الله، ولم يؤذ بها جيرانه؛ فلا حرج كونه يربي الحمام، أو الدجاج، أو غيرها من الطيور الطيبة المباحة؛ فلا بأس، بشرط ألا تشغله عما أوجب الله عليه، وبشرط ألا يؤذي بها عباد الله، فإذا كانت لا تشغله عما أوجب الله، ولا يؤذي بها عباد الله؛ فلا حرج عليه في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11214/صرف-الوقت-في-تربية-الحمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_504/50410.mp3","categories":["أحكام الحيوان"]},{"id":13184,"question":"يقول هذا السائل: ما حكم وضع الطيور في القفص من أجل النظر إليها، مع وضع الطعام لها في أوقاتها؟ مأجورين.","title":"حكم وضع الطيور في الأقفاص","answer":"الجواب:  لا أعلم حرجًا في ذلك، إذا وضع لها طعامها، ولم يجوعها، ولم يظلمها؛ فلا بأس؛ لأنه في هذه الحالة قد أكرمها، وأحسن إليها، قد يكون في ذلك فائدة للأطفال، أو لغير الأطفال إذا شاهدوها. فالمقصود: أنه إذا كان جعلها في الأقفاص لا يضرها، بل يطعمها ويسقيها؛ فلا حرج. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11439/حكم-وضع-الطيور-في-الاقفاص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51120.mp3","categories":["أحكام الحيوان"]},{"id":13492,"question":"تقول: لقد سمعت عن الكثير من الناس يقولون: بأن من يمسك بالهدهد محرم، هل هذا صحيح؟","title":"حكم الإمساك بالهدهد وقتله","answer":"الجواب: الهدهد لا يقتل، الرسول ﷺ نهى عن قتل الهدهد لا يقتل، لكن إذا أمسكه يكرمه ويطعمه ولا يقتله؛ لا حرج في ذلك، أما يمسكه للقتل ما يجوز، نعم.","link":"https://binbaz.org.sa/fatwas/11796/حكم-الامساك-بالهدهد-وقتله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51807.mp3","categories":["أحكام الحيوان"]},{"id":13619,"question":"فضيلة الشيخ! هذا السائل يقول: نحن سكان بادية، ونربي الأغنام والإبل، ونضع لها علامات على وجهها حتى يعرف كل شخص ماشيته، علمًا بأن هذه العلامات توضع بالكي بالنار، وتوضع على الأذن والأنف، فما حكم الشرع في نظركم في ذلك؟","title":"حكم وسم الأنعام لتمييزها","answer":"الجواب: لا يجوز الوسم في الوجه بالكي لا في الخشم، ولا في الخد، أما في الأذن لا بأس، الأذن من الرأس، الأذن تعتبر من الرأس؛ لا بأس بالوسم فيها، أما الوسم في وجه الدابة، في خدها، في أنفها فلا يجوز، ولا بأس بالوسم في فخذها .. في الرجل، أو في اليد .. في العضد لا بأس والرقبة، أما الوسم في الوجه لا يجوز -بالكي يعني- لا في الخد، ولا في الأنف، ولا في الجبهة، لا يجوز هذا. نعم.","link":"https://binbaz.org.sa/fatwas/11992/حكم-وسم-الانعام-لتمييزها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53411.mp3","categories":["أحكام الحيوان"]},{"id":13626,"question":"فضيلة الشيخ! هذا السائل يقول: نحن سكان بادية، ونربي الأغنام والإبل، ونضع لها علامات على وجهها حتى يعرف كل شخص ماشيته، علمًا بأن هذه العلامات توضع بالكي بالنار، وتوضع على الأذن والأنف، فما حكم الشرع في نظركم في ذلك؟","title":"حكم وسم الأنعام لتمييزها","answer":"الجواب: لا يجوز الوسم في الوجه بالكي لا في الخشم، ولا في الخد، أما في الأذن لا بأس، الأذن من الرأس، الأذن تعتبر من الرأس؛ لا بأس بالوسم فيها، أما الوسم في وجه الدابة، في خدها، في أنفها فلا يجوز، ولا بأس بالوسم في فخذها .. في الرجل، أو في اليد .. في العضد لا بأس والرقبة، أما الوسم في الوجه لا يجوز -بالكي يعني- لا في الخد، ولا في الأنف، ولا في الجبهة، لا يجوز هذا. نعم.","link":"https://binbaz.org.sa/fatwas/11992/حكم-وسم-الانعام-لتمييزها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53411.mp3","categories":["أحكام الحيوان"]},{"id":13673,"question":"تسأل هذه السائلة أم عبدالله عن قتل النمل المتواجد في المنزل بكثرة، هل يجوز قتله يا شيخ؟","title":"حكم قتل النمل الذي في المنازل","answer":"الجواب: إذا كان هذا النمل يؤذيهم؛ فلا بأس، أما إذا كان لا يؤذي؛ فلا يقتل، الرسول ﷺ نهى عن قتل النمل إلا إذا كان يؤذي، إذا آذاهم؛ فلا بأس أن يقتلوه بالمبيدات التي تبيده. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12018/حكم-قتل-النمل-الذي-في-المنازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52915.mp3","categories":["أحكام الحيوان"]},{"id":14068,"question":"فهذه رسالة وصلت إلى البرنامج من المستمع محسن حميد علي الصلاط من عزلة الأسلاف في اليمن، أخونا له سؤال يقول فيه: نحن في بلد صحراوي زراعي تكثر فيه القرود وهي تتلف المحاصيل الزراعية، هل لنا أن نضع لها السم كيما تموت ولا تؤذينا؟","title":"حكم قتل القرود التي تأكل المحاصيل","answer":"الجواب: نعم، إذا كانت القرود تؤذي فإنها تقتل بأي نوع من أنواع القتل مثلما تقتل الكلاب التي تعقر وتؤذي الناس وهكذا السنانير - القط - إذا آذى ولم يندفع شره إلا بالقتل يقتل كما تقتل السباع من الذئاب وغيرها، فهكذا القرود إذا آذت أصحاب المزارع ولم يندفع شرها إلا بالقتل فإنها تقتل بالسم وغيره وبالبنادق وبغير ذلك من الأسباب التي تدفع شرها، وهكذا الكلب العقور يقتل وهكذا الهر - القط - إذا آذى أهل البيت ولم يندفع شره إلا بذلك يقتل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12497/حكم-قتل-القرود-التي-تاكل-المحاصيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61306.mp3","categories":["أحكام الحيوان"]},{"id":14472,"question":"يقول: كنت أنا وزميلي مسافرًا برًا على الطريق الواصل إلى الرياض من المنطقة الجنوبية ليلًا، وفجأة اعترضنا أحد الجمال على هذا الخط ودهسناه بالسيارة بعد محاولة جادة لتلافي الحادث، ومات الجمل، فأسأل سماحة الشيخ: هل علينا شيء في ذلك؟ علمًا بأنني أنا صاحب السيارة، وزميلي هو السائق؟أثابكم الله.","title":"ما يلزم من دهس جملًا بالسيارة خطأً؟","answer":"الجواب: ليس عليك شيء؛ لأن الدولة قد نبهت أصحاب الجمال أن يصونوها عن الطرقات، ويمنعوها من الطرقات؛ لأنه يحصل بها حوادث كثيرة، ويموت بأسبابها جمع غفير من الناس، فالمجرم والمتعدي هو صاحب الجمل، حيث أطلقه وأهمله حول الطرقات، والحمد لله الذي سلمكم من شر هذا الجمل، فموت الجمل أسهل مما يصيب الناس من الأذى في سياراتهم، فليس عليكم شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12954/ما-يلزم-من-دهس-جملا-بالسيارة-خطا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62413.mp3","categories":["أحكام الحيوان"]},{"id":14566,"question":"هل قتل القطط أو الكلاب التي تتسبب في فساد الطيور، أو تقوم بأكلها هل هذا حرام؟ وإذا كانت والدتي قد قتلت مجموعة من القطط إحداها عن طريق الخنق، والآخر عن طريق الحرق بمياه النار الساخنة، بسبب تعذر الإمساك بهذه القطط، فماذا تفعل الآن إذا كان قتلها حرام؟","title":"حكم قتل القطط والكلاب المؤذية","answer":"الجواب: إذا كانت القطط أو الكلاب تؤذي كالكلب العقور، فإنه يقتل، كما قال النبي ﷺ: خمس من الدواب كلهن فواسق يقتلن في الحل والحرم: الغراب، والحدأة، والفأرة، والحية، والكلب العقور الكلب العقور يقتل في الحل والحرم، وهكذا القط الذي يؤذي يأكل الدجاج، يأكل الحمام، ولا ينفع طرده، بل يطرد ويأتي ويأكل ويؤذي فإنه يقتل.  أما إذا تيسر طرده وإبعاده من دون قتل، فإنه يكفي ولا يقتل، وكذلك لا يقتل بالنار؛ لأن النار لا يعذب بها إلا الله يقتل بغير النار، يقتل بالسم بالضرب إذا لم يتيسر الخلوص منه إلا بذلك.  أما إذا تيسر طرده وإبعاده وتخويفه حتى يبتعد فلا يقتل. فإذا اضطر الإنسان إلى قتل القط لإيذائه، وعدم التخلص منه بغير ذلك، فلا بأس لكن بغير النار، أما الكلب فلا يقتل إلا إذا كان عقورًا، ولكن يطرد إذا كان يؤذي يطرد، يطرد من المزرعة يطرد من الحارة يبعد ولا يقتل إلا إذا كان يؤذي الآخرين، إذا كان يعض الناس، يعقر الناس، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13063/حكم-قتل-القطط-والكلاب-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55604.mp3","categories":["أحكام الحيوان"]},{"id":14604,"question":"يقول فلاح السويد من قرية الكوز: إني أردت أن أذبح هرة مؤذية، ولكنني -يقول- اكتشفت أنها ما هي المؤذية، فما حكم الشرع فيّ يرحمكم الله؟","title":"حكم من أخطأ فقتل هرة يظنها المؤذية","answer":"الجواب: إذا كنت قتلتها لاعتقادك أنها مؤذية بأخذ -مثلًا- أكل الدجاج والحمام أو توسيخ الفرش هذا اعتقادك فلا شيء عليك، إذا بان لك أنك أخطأت في الاعتقاد.  وأما إذا كانت لا تؤذي فليس لك قتلها، بل يجب عليك ترك قتلها؛ لأنها من الطوافين، فعليك أن تحسن إليها بالطعام والشراب، وما يسر الله، ولا تقتلها، ولا تضربها أيضًا.  أما إن آذتك في أكل الدجاج -مثلًا- أو الحمام أو توسيخ الفرش بقاذوراتها بكونها غير أديبة؛ لأن بعض الهررة غير أديب، يؤذي ويوسخ الفرش، وبعضها لا، لا يفعل الأذى إلا في محلات خاصة بعيدة عن أذى الناس. فالحاصل: أنها إن آذت ولم يندفع أذاها إلا بالقتل تقتل، وإذا اندفع أذاها بغير قتل بأن تأخذها وتلقيها بعيدًا عن بيتك أو تحذرها؛ لأنها قد يخشى أن تكون من الجن المتجنسات بالهررة، تنذرها ثلاثة أيام، وتحذرها، فإن عادت فلا بأس بقتلها. فالحاصل: أنه لا يعجل في الأمور، ويتحرى فإذا ثبت أنها مؤذية، ولم يندفع أذاها إلا بالقتل قتلها، وإذا اندفع أذاها بغير ذلك من تحذيرها وتنبيهها لعلها تتوب إن كان يخشى أنها يعني: متجنسة من الجن، وإن كان أمكن أيضاً أن يحملها إلى محل بعيد ويلقيها بعيداً، ولا يقتلها فهذا أسلم وأولى، نعم.","link":"https://binbaz.org.sa/fatwas/13097/حكم-من-اخطا-فقتل-هرة-يظنها-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_558/55807.mp3","categories":["أحكام الحيوان"]},{"id":14610,"question":"يقول يا سماحة الشيخ: هل يجوز قتل القرود إذا كانت مؤذية، حيث تقوم هذه القرود بإتلاف بعض المحاصيل الزراعية؟وأيضًا نسأل عن قتل الثعالب؟ وما هي الحيوانات التي يجب قتلها؟","title":"حكم قتل الحيوانات المؤذية","answer":"الجواب: لا بأس بقتل الثعالب والقرود إذا آذت، مثلما قال ﷺ: خمس من الدواب يقتلن في الحل والحرم: الغراب والحدأة والفأرة والحية والكلب العقور كل هذه مثلها......، الغراب، والحدأة، والفأرة، والعقرب، والكلب العقور، وفي الرواية الأخرى: الحية، والسبع العادي، فكلها تقتل، فإذا آذاه القرد أو الهر -القط- لا بأس بقتله، إذا لم يتيسر السلامة منه بغير قتل.  أما إذا خوفه بشيء فلا حاجة إلى قتله، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13103/حكم-قتل-الحيوانات-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55904.mp3","categories":["أحكام الحيوان"]},{"id":14814,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العراقية، باعثتها إحدى المستمعات من هناك تقول الحاجة أم محمد، أم محمد تقول في رسالتها: إنني أم لعدة أولاد، وبعضهم متزوج ورب عائلة، وأولادي متدينون؛ يقيمون الصلاة والصيام ويحافظون على أمور دينهم.الشيخ: الحمد لله.المقدم: ولكنهم مغرمون جدًا بتربية الطيور في البيت، ويصرفون من أموالهم ووقتهم على العناية بها، وملاحظة تحليقها في الجو لساعة من النهار أو أكثر، وأخشى أن تكون هذه مخالفة للشرع، وجهونا وأفيدونا، جزاكم الله خيرًا.","title":"حكم تربية الطيور والاهتمام بها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلقد سرني كثيرًا ما ذكرت من استقامتهم ومحافظتهم على دينهم، فالحمد لله. أما تربية الطيور فلا حرج فيها، ولا بأس بها إذا كانت لا تؤذي أحدًا من الناس لا من الجيران ولا غيرهم، فإذا كانت طيورًا مباحة، ولا تؤذي أحدًا من الناس فلا بأس بتربيتها، ولا بأس بالنظر إليها حين طيرانها، كل ذلك لا حرج فيه إذا كانت لا تؤذي أحدًا.  أما إن كانت تؤذي فعليهم تقصيصها حتى لا تؤذي الجيران، ولا حرج في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13312/حكم-تربية-الطيور-والاهتمام-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64301.mp3","categories":["أحكام الحيوان"]},{"id":15318,"question":"هذا سؤال من المستمع نبيل ناظم مزاحم، من العراق، ناحية السعدية، يقول: أنا من محبي تربية الحيوانات الأليفة كالطيور وغيرها، ولكني معارض وبشدة من قبل أهلي على تلك التصرفات على أنه حرام أو مكروه، إلى آخره، وحسب ادعائهم أنها تجلب الشر، وتبعد الرزق عن البيت، أرشدوني إلى الصواب في هذا الموضوع حسب ما يتفق مع شريعتنا.جزاكم الله خيرًا.","title":"حكم تربية الحيوانات الأليفة","answer":"الجواب: لا نعلم حرجًا في تربية الطيور ونحوها كالدجاج والحمام، وكما تربى الأغنام وغير ذلك، هذه مثلها، فلا حرج في ذلك، والزعم بأن فيها شر، أو تجلب الشر على البيوت، كل هذا لا أصل له، بل هي لا حرج فيها، ولا بأس بها، فالطيور التي أباحها الله لا بأس بتربيتها كالحمام والدجاج وأشباه ذلك، مما يتربى في البيت، وينتفع به صاحب البيت بالبيع أو الأكل، كل هذا لا حرج فيه، كما تربى الأرانب، وتربى الأغنام وأشباهها، كالإبل والبقر، كل هذا لا بأس به، ولا حرج فيه إذا لم يكن فيه أذى، إذا كانت هذه الطيور لا تؤذي الجيران، بل تكون مقصوصة لا تؤذي الجيران أو طائرة، لكنها لا تؤذي الجيران فلا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/13820/حكم-تربية-الحيوانات-الاليفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67607.mp3","categories":["أحكام الحيوان"]},{"id":15409,"question":"يقول في سؤال من أسئلته: هل يجوز قطع نصف آذان الماعز؟ علمًا بأنهم يفعلون ذلك وذلك للجمال ولزيادة ثمنها.","title":"حكم قطع آذان الأنعام","answer":"الجواب: لا يجوز؛ لأن الرسول ﷺ نهى عن هذا، لا يجوز ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13912/حكم-قطع-اذان-الانعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56726.mp3","categories":["أحكام الحيوان"]},{"id":15410,"question":"بالنسبة لكي مكان قرن الماعز وهو صغير؛ لكي لا يطلع نهائيًا؛ وذلك أيضًا للجمال ولزيادة الثمن؟","title":"ما حكم كي مكان قرون الماعز؟","answer":"الجواب: لا أعلم في هذا بأسًا، أقول: لا أعلم في هذا بأسًا.","link":"https://binbaz.org.sa/fatwas/13914/ما-حكم-كي-مكان-قرون-الماعز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56727.mp3","categories":["أحكام الحيوان"]},{"id":15492,"question":"عندما أسقي الزرع أجد بعض النمل، وقد بنى له بيوتًا بجوار الأشجار، فأضطر إلى صب الماء عليه، فما الحكم في عملي هذا سماحة الشيخ؟","title":"حكم صب الماء على بيوت النمل","answer":"الجواب: إذا كان وجود النمل يضر أشجارك، فلا بأس، أما إذا كان لا يضر فلا تعرضه واتركه.","link":"https://binbaz.org.sa/fatwas/14021/حكم-صب-الماء-على-بيوت-النمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56909.mp3","categories":["أحكام الحيوان"]},{"id":16435,"question":"من أم عامر من الخبر رسالة وضمنتها هذا السؤال، يوجد في منزلنا كثير من النمل، وهو مؤذٍ، ولدغاته مؤلمة، لا تشفى إلا بعد معالجتها بالمطهرات، وأحيانًا حتى بعد تطهيرها يبقى أثر الألم لمدة يوم كامل، وأحيانًا أكثر من ذلك، و هل يجوز لنا قتل هذا النمل، وهل إن هذا الضرر الذي تسببه لنا سبب كافٍ للقضاء عليه؟ نرجو الإفادة، جزاكم الله خيرًا.","title":"جواز قتل المؤذي من النمل","answer":"الجواب: نعم، إذا آذاكم النمل؛ فاقتلوه، ولا بأس، لكن بغير النار بغير التحريق، يقتل بالمبيدات الأخرى غير النار، ولا حرج في ذلك لأذاه، كما تقتل الفواسق الخمس لأذاها، يقول النبي ﷺ: خمس من الدواب كلهن فواسق يقتلن في الحل والحرم: الغراب، والحدأة، والفأرة، والكلب العقور، والحدية. فالمقصود: أن المؤذيات من الحيوانات كهذه الخمس، وأشباهها، والذباب، والجعران، والنمل، وكل شيء يؤذي من هذه الأشياء لا بأس بقتله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15132/جواز-قتل-الموذي-من-النمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71508.mp3","categories":["أحكام الحيوان"]},{"id":17038,"question":"يقول السائل (م. م) يوجد في الأسواق جهاز كهربائي يسمى صائد الحشرات، حيث يقوم هذا الجهاز بصعق الحشرة، وتموت، هل هذا يعتبر من التحريق بالنار؟ وهل يجوز بيعه، واقتناؤه؟","title":"ما حكم قتل الحشرات بالصاعق الكهربائي؟","answer":"الجواب: لا يجوز الإحراق بالنار، ولكن يحرق بغير النار يعني: يبيده بغير النار، أما الإحراق بالنار الرسول ﷺ نهى عن التعذيب بالنار، وقال: لا يعذب بها إلا الله فإذا كان هناك ما يؤذيه من بعوض، أو نمل، أو كذا بغير النار. نعم.","link":"https://binbaz.org.sa/fatwas/15826/ما-حكم-قتل-الحشرات-بالصاعق-الكهرباىي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58715.mp3","categories":["أحكام الحيوان"]},{"id":17263,"question":"هذا سائل محمد صالح يقول في هذا  نحن نسكن في منطقة ريفية، وتحت بيتنا ثلاثة من الكلاب للحراسة نعتني بها، وقرأت حديثًا عن الرسول ﷺ: من ربى كلبًا ينقص من أجره في كل يوم قيراطان هل نأثم في تربيتنا لمثل هذه الكلاب للحراسة، مع العلم بأن هذه الكلاب لا تؤذي أحدًا من الناس، أفيدونا سماحة الشيخ؟","title":"حكم اتخاذ الكلاب للحراسة","answer":"الجواب: يقول النبي ﷺ: من اقتنى كلبًا إلا كلب صيدٍ، أو ماشية، أو زرع  فإنه ينقص من أجره كل يوم قيراطان فلم يستثن إلا كلب الصيد، وكلب الماشية، وكلب الزرع. فالذي أنصحكم به أن تبعدوا هذه الكلاب، وألا تجعلوها حرسًا لكم، أبعدوها، واجعلوا حرسًا من الرجال، إذا كان في حاجة فاجعلوا رجلًا يكون حارسًا بالأجرة، هذا هو المشروع، أما جعل الكلاب لا، الكلاب لا تقتنى إلا لأحد ثلاثة: إما للصيد، أو الماشية الغنم، أو الزرع الحرث، هذا الذي رخص فيه النبي ﷺ. نعم.","link":"https://binbaz.org.sa/fatwas/16102/حكم-اتخاذ-الكلاب-للحراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59214.mp3","categories":["أحكام الحيوان"]},{"id":17264,"question":"يقول السائل محمد صالح: سماحة الشيخ نلاحظ عندنا في منطقتنا ذبح الماشية الكبيرة السن خصوصًا الغنم، وعند سؤالهم عن ذلك يقولون بأنها ستموت من مرض، أو شبهه، معللين ذلك بأن هذا يريح هذه البهيمة من مرضها، هل يجوز ذلك؟ أم يجوز أن نتركها تعاني من المرض حتى تموت؟ أفيدوني مأجورين.","title":"حكم ذبح الماشية التي يخشى موتها","answer":"الجواب: إذا تيسر ذبحها حتى ينتفع بها فهو أصلح من تركها تموت، إذا تيسر ذبحها حتى ينتفع بها بعض الناس، يستفيد منها بعض الناس؛ يكون أفضل، أفضل من تركها تموت، وأما إذا كان لا فائدة فيها؛ فلا بأس، إن تركها تموت فلا بأس، وإن ذبحها فلا بأس، الأمر واسع، إن شاء الله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16103/حكم-ذبح-الماشية-التي-يخشى-موتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59215.mp3","categories":["أحكام الحيوان"]},{"id":18050,"question":"رسالة بعث بها أحد الإخوة المستمعين، يقول: أبو حامد من الرياض، أخونا يسأل عن عدد من القضايا، من بينها قضية يسأل عنها، ألا وهي: وضحوا لنا مسألة دهس الحيوانات بالسيارة بغير قصد، مثل القطط، والكلاب، أجلكم الله، والغنم، والجمال، وما أشبه ذلك، ولاسيما إذا كان ذلك في الطرق السريعة، هل علينا كفارات؟ أو ما يشبه الديات؟ جزاكم الله خيرًا.","title":"حكم دهس الحيوانات بالسيارات","answer":"الجواب: ليس للمسلم أن يتعمد دهس الدواب، لا قط، ولا كلب، ولا حيوان آخر، لا يجوز له قتلها بغير حق، لكن إذا وقع من غير قصد، فلا شيء عليه، إذا وقع دهس قط، أو كلب، ليس عليه شيء، أما إذا كان الحيوان مملوكًا كالغنم، والإبل، يضمنها لأهلها، إذا تعمد دهسها، أو دهسها بسبب السرعة، أو بسبب النعاس، أو ما أشبه ذلك. أما إذا كان ما تعمد، ولا أسرع، ولا نام، ولكن هجمت عليه، فهي غير مضمونة، غير مضمونة، بل صاحبها هو الذي أخطأ، وأرسلها في الطرقات. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17083/حكم-دهس-الحيوانات-بالسيارات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72908.mp3","categories":["أحكام الحيوان"]},{"id":18063,"question":"هذه سائلة (ش . س. ع) تسأل تقول: تركت أرانب في برميل بالشمس من المغرب إلى المغرب من اليوم الآخر بلا طعام ولا شراب، وخرجت عن البيت غافلة عنها، فماتت، فهل علي إثم بذلك؟","title":"هل يأثم من قتل الحيوان بغير قصد؟","answer":"الجواب: إذا كانت غير متعمدة فلا إثم عليها، إذا كنت أيتها السائلة غير متعمدة، وإنما غفلت عنها ونسيت فلا حرج إن شاء الله، لكن إن كانت لغيرك فعليك ضمانها، إن كانت الأرانب لغيرك فعليك الضمان، إلا أن يسمح أصحابها عن ذلك. أما إن كانت لك فليس عليك شيء ولكن عليك الحذر من مثل هذا في المستقبل، وأن تفعلي الشيء الذي فيه الاحتياط. نعم.","link":"https://binbaz.org.sa/fatwas/17098/هل-ياثم-من-قتل-الحيوان-بغير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_901/nour_90106.mp3","categories":["أحكام الحيوان"]},{"id":18562,"question":"أخونا يسأل هذا السؤال ويقول: فتح فم الطير وإعطاؤه الحبوب، وربما تكون أكثر من طاقته حتى يسمن بسرعة، هل هذا جائز أو لا؟","title":"حكم إطعام الحيوان أكثر من طاقته لأجل تسمينه","answer":"الجواب: هذا فيه تفصيل: يخشى منه، إذا كان الطائر مريض يعني: يحتاج إلى من يلقمه، فلا بأس يعطى قدر الحاجة، مع الاحتياط لئلا يضره، فأما إذا كان الطائر يلقط بنفسه، ويأكل بنفسه فلا حاجة إلى هذا العمل؛ لأن هذا قد يضره ويؤذيه، ونحن مأمورون بالرفق بالحيوان، وعدم إيذائه، وعدم ظلمه، وعدم ضربه، إلا من حاجة، فكونه يعطيه الطعام مع فمه بالقوة لقصد أن هذا يكون تسمينًا له فهذا لا ينبغي؛ لأنه يخشى فيه الضرر. فالمقصود: أن الواجب التفصيل: إذا كان الطائر والحيوان سليمًا يأكل بنفسه، ويلقط الحب بنفسه، فلا حاجة إلى هذا كله، أما إذا كان مريضًا، يعجز عن الأكل يحتاج إلى من يرفع له الطعام مثل بني آدم يساعد، يساعد على وجه لا يضر، نعم. المقدم: لكن إذا كان المقصود من هذا كما قال: أن يسمن بسرعة؟ الشيخ: لا ما يصلح، لا يصلح إذا كان يضره، أما إذا كان لا يضره، ولكن يدر عليه الطعام، ويجتهد في علفه الجيد هذا لا بأس لكن على وجه يضره يؤذيه لا. المقدم: جزاكم الله خيرًا، ونفع بعلمكم، رأيت أناسًا سماحة الشيخ! يحقنون الطيور بالماء عند بيعها من أجل أن تكون على هيئة معينة عند البيع ربما يكون في هذا شيء من التدليس؟ الشيخ: هذا لا يجوز؛ لأن هذا معناه التدليس يوهم الناس أنها سمينة، وأنها كبيرة والأمر ليس كذلك، كل شيء يوهم المشتري والزبون خلاف الحقيقة لا يجوز؛ لأن الرسول  قال: من غشنا فليس منا هكذا يقول ﷺ: من غشنا فليس منا «ولما مر على صبرة من طعام في السوق وأدخل يده فيها نالت أصابعه بللاً فقال: ما هذا يا صاحب الطعام؟ قال: أصابته السماء يا رسول الله -يعني: المطر- قال: أفلا جعلته فوق الطعام كي يراه الناس، من غش فليس مني رواه مسلم في الصحيح. فالمقصود: أن الواجب على المسلمين التناصح وعدم الغش، فكل شيء يجعل المشتري على غير الحقيقة في بيع الحيوان أو غير الحيوان لا يجوز. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17674/حكم-اطعام-الحيوان-اكثر-من-طاقته-لاجل-تسمينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91704.mp3","categories":["أحكام الحيوان"]},{"id":18973,"question":"أختنا يبدو أنها من الأسر التي ابتليت بتربية الكلاب، فتسأل وتقول: إذا لمسنا الكلب، ثم أردنا أن نصلي فما الحكم؟","title":"حكم تربية الكلاب ولمسها","answer":"الجواب: إن كان الكلب يابسًا، واليد يابسة فلا شيء، ليس على من لمسه شيء، أما إن كان الكلب رطبًا، أو اليد رطبة فليغسلها سبع مرات بالماء تحت كباس يغسلها سبع مرات، وإذا جعل في ذلك ترابًا يكون أحسن أيضًا كالولوغ؛ لأن الرسول ﷺ أمر بالتراب في الولوغ في إحدى الغسلات السبع، فإذا لمس الكلب، أو لمس لعابه، أو بوله يغسله سبع مرات، ويكون فيها تراب، فإن لم يتيسر صابون أو إشنان يقوم مقام ذلك والتراب أولى؛ لأنه جاء به النص. ولا ينبغي أن تربى الكلاب، ولا ينبغي أن تقتنى الكلاب إلا في ثلاث: للصيد، وللمزرعة -المزارع- وللماشية -الغنم- لأجل وجوده فيها يحميها -بإذن الله- من الذئاب، وينبه أهلها حتى يلاحظوها، والرسول ﷺ قال: من اقتنى كلبًا إلا كلب صيد، أو ماشية، أو زرع؛ فإنه ينقص من أجره كل يوم قيراطان كيف يرضى مسلم لنفسه أن ينقص من أجره كل يوم قيراطان باقتنائه كلبًا لا حاجة إليه لا لماشية ولا صيد ولا زرع، فإذا كنت تقتنين الكلاب فاحذري ذلك وأبعديها، ولا تقتنيها أبدًا إلا لأحد الثلاث: للصيد أو لمزرعة أو للغنم الماشية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18112/حكم-تربية-الكلاب-ولمسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_924/nour_92413.mp3","categories":["أحكام الحيوان"]},{"id":19515,"question":"السائل عبد الله من مكة المكرمة يقول في سؤاله الثاني: يوجد لدينا أغنام فظهر فيها مرض وهو أورام في خارج جسمها، فقامت والدتي ووضعت عليها علاج، فماتت تلك الأغنام التي وضعنا عليها العلاج وعددها تسعة، وهي لا تعلم بأن هذا يضرها، وهي غير قاصدة أيضًا بقتلها، بل تريد علاجها من هذا المرض؛ لأنها سمعت من بعض الناس لأنهم يقولون: بأن هذا العلاج يشفي بإذن الله من هذا المرض، فندمت والدتي لفعلها ذلك ندمًا شديدًا فهل عليها إثم، وهل عليها كفارة؟","title":"حكم وضع دواء لحيوان أدى إلى موته","answer":"الجواب: إذا كان الذي أخبرها ممن يتعاطى الطب فلا شيء عليها، أما إذا كان من عامة الناس فلا يجوز التطبب بغير بصيره، فعليها ألا تعود لمثل هذا، وإذا غرمتها لكم فذلك من باب الحيطة، إذا غرمت إذا كانت موسرة وغرمتها لكم فهذا من باب الحيطة، وإن سامحتموها جزاكم الله خيرًا. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18762/حكم-وضع-دواء-لحيوان-ادى-الى-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94612.mp3","categories":["أحكام الحيوان"]},{"id":19516,"question":"سماحة الشيخ! هذا السائل عبد الله من مكة المكرمة يقول: نحن نسكن في البادية ولدينا أغنام، فتذهب هذه الأغنام لترعى وحدها في الجبال، وبدون راعي يحرسها، فتأكل منها الذئاب والسباع تقريبًا في كل شهر، وبعضها قد ينزل في أماكن لا نستطيع الوصول إليها لإخراجها من هذه الأماكن فتموت من العطش والجوع، ونحن لا نستطيع الذهاب لنقوم بحراستها، والسؤال يا سماحة الشيخ! هل نحاسب على تركنا لهذه الأغنام لترعى وحدها، وماذا نفعل وجهونا مأجورين؟","title":"حكم ترك الأغنام بغير راع وأكل الذئاب منها والسباع","answer":"الجواب: إذا كان الواقع هو ما ذكره السائل فإني أخشى عليكم أن تأثموا؛ لأن هذا من إضاعة المال، والرسول ﷺ نهى عن إضاعة المال، فالواجب أن تجعلوا معها راعيًا يصونها، ويرعيها في المراعي الحسنة، وإلا فبيعوها، وأنفقوا ثمنها في المصالح، وتصدقوا، أما إهمالها، وإضاعتها فالرسول ﷺ نهى عن إضاعة المال، وأخشى عليكم أن تأثموا؛ لأن هذا العمل معناه إضاعتها للذئاب أو الموت. فالواجب أن يوضع فيها حارس يصونها ويرعيها في المراعي الحسنة، ويصونها عن الذئاب، وعن المواضع التي فيها الخطر، وإلا فبيعوها، وأنفقوا ثمنها في مصالح العامة. نعم.","link":"https://binbaz.org.sa/fatwas/18761/حكم-ترك-الاغنام-بغير-راع-واكل-الذىاب-منها-والسباع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94611.mp3","categories":["أحكام الحيوان"]}]
